import os
from flask import Flask, render_template
from flask_sqlalchemy import SQLAlchemy
from flask_cors import CORS
from configuration import get_config

db = SQLAlchemy()

# 项目根目录
BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def create_app(config_name=None):
    """应用工厂函数"""
    # 设置模板路径
    template_dir = os.path.join(BASE_DIR, 'templates')
    app = Flask(__name__, template_folder=template_dir)

    # 加载配置
    if config_name:
        app.config.from_object(config_name)
    else:
        app.config.from_object(get_config())

    # 初始化扩展
    db.init_app(app)

    # CORS 支持
    CORS(app)

    # ==== 在这里注册业务蓝图 ====
    from app.routes.image_routes import image_bp
    from app.routes.blog_routes import blog_bp
    app.register_blueprint(image_bp, url_prefix='/api/images')
    app.register_blueprint(blog_bp, url_prefix='/api/blogs')
    # ==============================

    # 首页路由
    @app.route('/')
def index():
    return render_template('blog_list.html')

    @app.route('/blogs/new')
    def blog_create():
        return render_template('blog_create.html')
    # 健康检查
    @app.route('/health')
    def health():
        return {'status': 'ok'}

    @app.route('/blogs/<int:id>')
    def blog_detail(id):
        return render_template('blog_detail.html', blog_id=id)

    # 创建数据库表
    with app.app_context():
        db.create_all()

    return app

from flask import Blueprint, request, jsonify
from app.models.blog import Blog
from app import db
from app.utils.image_utils import save_image

blog_bp = Blueprint('blog', __name__)

@blog_bp.route('/', methods=['GET'])
def get_all_blogs():
    blogs = Blog.query.all()
    return jsonify([blog.to_dict() for blog in blogs])

@blog_bp.route('/<int:blog_id>', methods=['GET'])
def get_blog_by_id(blog_id):
    blog = Blog.query.get(blog_id)
    if not blog:
        return jsonify({'error': 'Blog not found'}), 404
    return jsonify(blog.to_dict())

@blog_bp.route('/', methods=['POST'])
def create_blog():
    data = request.form
    title = data.get('title')
    content = data.get('content')
    images = request.files.getlist('images')

    if not title or not content:
        return jsonify({'error': 'Title and content are required'}), 400

    image_urls = []
    for image in images:
        image_url = save_image(image)
        image_urls.append(image_url)

    blog = Blog(title=title, content=content, images=image_urls)
    db.session.add(blog)
    db.session.commit()

    return jsonify(blog.to_dict()), 201

@blog_bp.route('/<int:blog_id>', methods=['PUT'])
def update_blog(blog_id):
    blog = Blog.query.get(blog_id)
    if not blog:
        return jsonify({'error': 'Blog not found'}), 404

    data = request.form
    title = data.get('title')
    content = data.get('content')
    images = request.files.getlist('images')

    if title:
        blog.title = title
    if content:
        blog.content = content
    if images:
        image_urls = []
        for image in images:
            image_url = save_image(image)
            image_urls.append(image_url)
        blog.images = image_urls

    db.session.commit()

    return jsonify(blog.to_dict())

@blog_bp.route('/<int:blog_id>', methods=['DELETE'])
def delete_blog(blog_id):
    blog = Blog.query.get(blog_id)
    if not blog:
        return jsonify({'error': 'Blog not found'}), 404

    db.session.delete(blog)
    db.session.commit()

    return jsonify({'message': 'Blog deleted successfully'})

import os
from flask import Blueprint, request, jsonify
from werkzeug.utils import secure_filename

image_bp = Blueprint('image', __name__)

UPLOAD_FOLDER = 'app/static/uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}

# Ensure the upload folder exists
os.makedirs(UPLOAD_FOLDER, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@image_bp.route('/upload', methods=['POST'])
def upload_image():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']

    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        file_path = os.path.join(UPLOAD_FOLDER, filename)
        file.save(file_path)
        return jsonify({'url': f'/static/uploads/{filename}'}), 201

    return jsonify({'error': 'File type not allowed'}), 400
